def longest_consecutive(nums: list[int]) -> int:
    num_set = set(nums)
    max_len = 0
    for x in num_set:
        if x - 1 not in num_set:
            cur = x
            current_len = 1
            while cur + 1 in num_set:
                cur += 1
                current_len += 1
            max_len = max(max_len, current_len)
    return max_len
